// Browser-only configuration sample. Secret text is deliberately never collected.
export function configurationPage({state,save,projects,esc,getId,render,currentName}) {
 const views=new Map();
 const view=()=>{const id=getId();if(!views.has(id))views.set(id,{status:'ready',preview:false});return views.get(id)};
 const read=()=>{const s=state(getId());return s.editorDraft||{name:currentName(),mode:s.mode,host:s.connection.host,port:s.connection.port,secret:'keep'}};
 const input=(label,key,value,type='text')=>`<div class="field"><label for="edit-${key}">${label}</label><input id="edit-${key}" name="${key}" value="${esc(value)}" type="${type}" ${type==='number'?'min="1" max="65535" step="1"':''} required aria-describedby="edit-error"></div>`;
 const button=(label,act,primary=false)=>`<button type="button" data-edit="${act}" ${primary?'class="primary"':''}>${label}</button>`;
 function page(){
  const s=state(getId()),v=view(),d=read(),dirty=!!s.editorDraft,scope=projects[getId()].parent?'仅当前模块；其他模块及共享 Root 不变':'仅当前工程；共享个人配置不变';
  const statuses={ready:['配置已读取','修改前先核对来源；本页使用虚构数据。'],loading:['正在读取配置','正在核对工程信息、连接来源与配置版本。'],empty:['尚未配置开发连接','已有业务文件会保留。创建演示连接后继续配置。'],failed:['配置未保存','模拟写入失败，原配置未变；输入已保留，可以重试。'],partial:['配置已保存，验证未完成','演示值已保存；客户端加载尚未确认，请继续检查。'],saved:['已保存并读回演示配置','浏览器中的值已更新；真实工程及客户端未执行。']};
  const [title,description]=statuses[v.status]||statuses.ready;
  return `<div class="page-heading"><div><h2>工程配置</h2><p>交互预览 · 仅保存浏览器演示数据，不读写真实工程。</p></div></div><details class="state-review"><summary>状态验收</summary><div class="actions">${[['ready','正常'],['loading','加载'],['empty','空态'],['failed','失败'],['partial','部分完成']].map(([k,n])=>button(n,'state-'+k)).join('')}</div><small>只切换界面状态，不操作工程。</small></details><div class="feedback ${v.status}" role="status" aria-live="polite"><strong>${dirty&&v.status==='ready'?'有未保存的修改':title}</strong><p>${description}</p>${v.status==='loading'?button('完成模拟读取','state-ready'):v.status==='empty'?button('创建演示连接','state-ready',true):v.status==='partial'?button('重新检查演示结果','verify',true):''}</div>${['empty','loading'].includes(v.status)?`<section class="config-section" aria-busy="${v.status==='loading'}">${v.status==='loading'?'<div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div>':'<h3>先准备一组开发连接</h3><p>无需重复填写已有配置；真实接入后会优先读取原来源。</p>'}</section>`:`<div class="configuration-layout"><form id="polished-config" novalidate><section class="config-section"><div class="section-heading"><h3>工程信息</h3><p>展示名称与开发方式</p></div><div class="form-grid">${input('项目显示名称','name',d.name)}<div class="field"><label for="edit-mode">开发方式</label><select id="edit-mode" name="mode"><option value="connected" ${d.mode==='connected'?'selected':''}>连接开发</option><option value="offline" ${d.mode==='offline'?'selected':''}>离线开发</option></select><span class="field-origin">切换不删除已有连接</span></div></div></section><section class="config-section"><div class="section-heading"><h3>IRIS 开发连接</h3><details class="inline-source"><summary>来源与影响范围</summary><p>${scope}</p><code>.agents/config/project-env.json</code><p>正式接入需核对 .mcp.json 与受管 backend；当前未接管。</p></details></div><div class="form-grid connection-grid">${input('连接地址','host',d.host)}${input('Web 端口','port',d.port,'number')}</div><div class="credential-row"><div><label for="edit-secret">连接凭据</label><p>${s.connection.secret?'已设置（演示）':'未设置（演示）'} · 不回显原值</p></div><select id="edit-secret" name="secret" aria-describedby="secret-help"><option value="keep" ${d.secret==='keep'?'selected':''}>保留现有凭据</option><option value="replace" ${d.secret==='replace'?'selected':''}>模拟替换凭据</option><option value="clear" ${d.secret==='clear'?'selected':''}>清除演示凭据</option></select></div><p id="secret-help" class="field-help">原型不接收真实密码或 Key。替换仅演示状态；清除会在保存预览中再次标明。</p></section><p id="edit-error" class="field-error" role="alert">${esc(v.error||'')}</p>${v.preview?`<section class="change-preview"><h3>核对本次修改</h3><dl><dt>影响范围</dt><dd>${scope}</dd><dt>保存位置</dt><dd>当前浏览器的工程演示数据</dd><dt>连接</dt><dd>${esc(d.host)} : ${esc(d.port)}</dd><dt>凭据</dt><dd>${d.secret==='clear'?'将清除演示凭据':d.secret==='replace'?'将模拟替换；不保存任何密钥文本':'保留现有值'}</dd></dl><div class="actions">${button('返回编辑','back')}${button('模拟保存并检查','apply',true)}${button('模拟保存失败','fail')}${button('模拟部分完成','partial')}</div></section>`:''}<div class="save-bar"><div id="edit-status" role="status">${dirty?'未保存 · 草稿仅保存在本浏览器':'没有待保存的修改'}</div><div class="actions">${button('放弃修改','discard')}<button class="primary" type="submit" ${!dirty?'disabled':''}>预览修改</button></div></div></form><aside class="source-panel"><details><summary>更多配置与共享连接</summary><p>个人共享配置可能影响其他引用工程，须独立核对。</p><div class="actions"><button type="button" data-action="scope-open:identity">接管配置</button><button type="button" data-action="scope-open:web">Web / SFTP</button><button type="button" data-action="scope-open:profiles">领域配置</button><button type="button" data-action="scope-open:bos">BOS 配置</button><button type="button" data-action="scope-open:embedding">知识 Key</button></div></details></aside></div>`}`;
 }
 function capture(){const f=document.querySelector('#polished-config');if(!f)return;const d=Object.fromEntries(new FormData(f));state(getId()).editorDraft=d;save();view().preview=false;document.querySelector('.change-preview')?.remove();const feedback=document.querySelector('.feedback');if(feedback&&['ready','saved'].includes(view().status)){view().status='ready';feedback.className='feedback ready';feedback.querySelector('strong').textContent='有未保存的修改';feedback.querySelector('p').textContent='修改尚未应用；预览后再保存演示配置。'}const bar=document.querySelector('#edit-status');if(bar)bar.textContent='未保存 · 草稿仅保存在本浏览器';f.querySelector('[type=submit]').disabled=false;}
 document.addEventListener('input',e=>{if(e.target.closest('#polished-config'))capture()});
 document.addEventListener('change',e=>{if(e.target.closest('#polished-config'))capture()});
 document.addEventListener('submit',e=>{if(e.target.id!=='polished-config')return;e.preventDefault();capture();const d=read(),v=view();v.error='';for(const k of ['name','host','port'])document.getElementById('edit-'+k).removeAttribute('aria-invalid');const key=!d.name.trim()?'name':!d.host.trim()?'host':!Number.isInteger(Number(d.port))||Number(d.port)<1||Number(d.port)>65535?'port':null;if(key){v.error=key==='port'?'Web 端口请输入 1–65535 的整数。':'项目名称和连接地址不能为空。';render();const el=document.getElementById('edit-'+key);el.setAttribute('aria-invalid','true');el.focus();return}v.preview=true;render();document.querySelector('.change-preview').scrollIntoView({block:'nearest'});});
 document.addEventListener('click',e=>{const a=e.target.closest('[data-edit]')?.dataset.edit;if(!a)return;const v=view(),s=state(getId());if(a.startsWith('state-')){v.status=a.slice(6);v.preview=false}else if(a==='discard'){delete s.editorDraft;v.preview=false;v.status='ready';v.error='';save()}else if(a==='back'){v.preview=false}else if(a==='fail'){v.status='failed';v.preview=false}else if(a==='verify'){v.status='saved'}else if(['apply','partial'].includes(a)){const d=read();s.name=d.name.trim();s.mode=d.mode;s.connection.host=d.host.trim();s.connection.port=Number(d.port);if(d.secret!=='keep')s.connection.secret=d.secret==='replace';delete s.editorDraft;save();v.status=a==='partial'?'partial':'saved';v.preview=false}render();});
 return page;
}
